// src/components/Navigation.js
import React from "react";
import { Navbar, Nav, NavDropdown, Button, Container } from "react-bootstrap";
import { Link } from "react-router-dom";

const Navigation = () => {
  return (
    <Navbar
      expand="lg"
      variant="dark"
      style={{ backgroundColor: "#2d2d2d" }}
    >
      <Container>
        {/* Brand: Fi */}
        <Navbar.Brand as={Link} to="/" className="fw-bold fs-3" style={{ color: "#28c7b7" }}>
          Fi
        </Navbar.Brand>

        <Navbar.Toggle aria-controls="navbarNav" />
        <Navbar.Collapse id="navbarNav" className="justify-content-end">
          <Nav>
            {/* ABOUT US Dropdown */}
            <NavDropdown title="ABOUT US" id="aboutus-dropdown">
              <NavDropdown.Item as={Link} to="/whats-fi">What’s Fi</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/team">Team</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/careers">Careers</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/contact-us">Contact us</NavDropdown.Item>
            </NavDropdown>

            <Nav.Link as={Link} to="/cards">CARDS</Nav.Link>
            <Nav.Link as={Link} to="/features">FEATURES</Nav.Link>
            <Nav.Link as={Link} to="/accounts">ACCOUNTS</Nav.Link>
            <Nav.Link as={Link} to="/resources">RESOURCES</Nav.Link>
            <Nav.Link as={Link} to="/help">HELP</Nav.Link>

            {/* DOWNLOAD FI Button */}
            <Button variant="outline-light" className="ms-3">
              DOWNLOAD FI
            </Button>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
};

export default Navigation;
